{
  "bioavailability_prediction": "low",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C01","C04","C07","C09","C10","C11","C12","C14","C16","C20","C23","C24","C25","C36","C41","C42","C65","C58"],
  "contradictory_card_ids": ["C30","C40"],
  "prediction_basis_card_ids": ["C01","C09","C11","C23","C36","C41","C65"],
  "claims": [
    {
      "claim": "Direct human absolute oral bioavailability values for steroid-like molecules are consistently below 20%: β-sitosterol 0.41% (C01, C14, C20), testosterone 3.66% (C09), testosterone undecanoate 6.8% (C11, C24), danazol 11–19% fasted (C04, C07, C12, C25), and abiraterone acetate <10% fasted (C10, C16, C23).",
      "card_ids": ["C01","C04","C07","C09","C10","C11","C12","C14","C16","C20","C23","C24","C25"]
    },
    {
      "claim": "Phenol-bearing steroids undergo first-pass glucuronidation; fulvestrant's poor oral bioavailability is attributed to UGT-mediated inactivation in the GI tract and liver (C36, C08, C18, C21, C22), and the query contains a phenol and a 1,2-diol matching this liability.",
      "card_ids": ["C36","C08","C18","C21","C22"]
    },
    {
      "claim": "L4 solubility records show that the structurally similar steroid estradiol has low aqueous solubility (1.81 ± 0.19 µg/mL without BSA, C65; 7.3 µM in medium, C58; increased apparent solubility with BSA, C67), supporting dissolution-limited absorption for phenolic steroids.",
      "card_ids": ["C65","C58","C67"]
    },
    {
      "claim": "L4 dissolution records for other molecules (hydrocortisone, prednisolone, methyltestosterone, THC, hydromorphone, E804) are not query-specific and do not provide direct F evidence; formulation-dependent improvements do not establish unformulated oral bioavailability.",
      "card_ids": ["C56","C57","C60","C61","C62","C63","C64","C66"]
    },
    {
      "claim": "C30 (stigmasterol 43.83%) and C40 (DMAU described as orally bioavailable) are not transferable or conflict with measured low-F evidence (C06, C38), so they do not outweigh the consistent low-F steroid pattern.",
      "card_ids": ["C30","C40","C06","C38"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C56","C57","C58","C59","C60","C61","C62","C63","C64","C65","C66","C67"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "No query-specific human PK, AUC, Cmax, dose, or formulation data are available.",
    "L4 records are for other molecules (estradiol, THC, hydrocortisone, etc.), not for the query.",
    "First-pass conjugation for the query is inferred from the fulvestrant phenol-glucuronidation context (C36) rather than measured.",
    "Query solubility and permeability are not experimentally measured.",
    "Transfer from steroid analogs is indirect; exact structural match to a training context is not established."
  ],
  "decision_summary": "Prediction remains low. L1/L2 direct and quantitative steroid evidence (absolute F 0.41–19% in humans; 0.7% for oleanolic acid in rats; phenol-glucuronidation mechanism for fulvestrant) supports F < 20%. L4 solubility/dissolution records add supportive context for dissolution-limited absorption of phenolic steroids (estradiol solubility ~1.8 µg/mL) but are not direct F measurements and do not change the decision."
}

